UPDATE collab_view v SET config=v.config-'visibleFields',version=version+1 FROM collab_table t WHERE t.id=v."tableId" AND t.source='CASES' AND v."isDefault"=true AND v.shared=true;
UPDATE collab_table SET "schemaVersion"="schemaVersion"+1 WHERE source='CASES';
